WECHAT_TEXT = f"微信图片（随手拍，与本案无关）\n{FEAT}"
SCAN_TEXT = {"03一审/我方证据/微信图片_20260301.jpg": [WECHAT_TEXT]}


def build(root: Path) -> None:
    d = root / CASE
    for rel, pages in PDFS.items():
        p = d / rel
        p.parent.mkdir(parents=True, exist_ok=True)
        C.text_pdf(p, pages, FEAT)
    (d / "03一审/我方文件").mkdir(parents=True, exist_ok=True)
    doc = Document()
    C.set_east_asian_font(doc, "仿宋")
    C.fix_core(doc, "民事起诉状", FEAT)
    for t in QISUZHUANG:
        doc.add_paragraph(t)
    doc.save(d / "03一审/我方文件/民事起诉状.docx")

    im = C.screenshot_image([("随手拍", 48, (60, 60, 60)), (FEAT, 30, (120, 120, 120))], size=(640, 480))
    C.save_jpeg(im, d / "03一审/我方证据/微信图片_20260301.jpg", FEAT)

    # Word 打开文件时留下的所有者文件：前 54 字节是用户名，这里放特征字符串
    owner = bytearray(162)
    name = FEAT.encode("ascii")
    owner[0] = len(name)
    owner[1:1 + len(name)] = name
    (d / "03一审/我方文件/~$起诉状.docx").write_bytes(bytes(owner))
